tasks.curl:
export REF_IMAGE=/absolute/path/to/reference.png

DATA_URI="data:image/png;base64,$(base64 -w0 "$REF_IMAGE")"
curl -sS --fail-with-body \
  -X POST http://localhost:8099/v1/chat/completions \
  -H 'Content-Type: application/json' \
  -d "{
    \"model\": \"flux-3-image-klein\",
    \"messages\": [{
      \"role\": \"user\",
      \"content\": [
        {\"type\": \"text\", \"text\": \"restyle as a watercolor painting with soft pastel tones\"},
        {\"type\": \"image_url\", \"image_url\": {\"url\": \"${DATA_URI}\"}}
      ]
    }],
    \"seed\": 42,
    \"height\": 1024,
    \"width\": 1024
  }" | python3 -c 'import base64,json,sys; u=json.load(sys.stdin)["choices"][0]["message"]["content"][0]["image_url"]["url"]; open("i2i.png","wb").write(base64.b64decode(u.split(",",1)[1]))'
